const assert = require('node:assert/strict');
const fs = require('node:fs');
const vm = require('node:vm');
const { createMessageQueue } = require('../miniprogram/services/message-alert-state');
const source = fs.readFileSync('miniprogram/services/message-alert-state.js', 'utf8');
assert.equal(
  fs.readFileSync('dist/shared/message-alert-state.js', 'utf8'),
  '// Generated by tools/sync-message-alert-state.cjs.\n' +
    source.replace('module.exports = { createMessageQueue };', 'export { createMessageQueue };'),
);
const item = (id, time) => ({
  id,
  type: 'message',
  target: '#conversation/aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
  createdAt: time,
});
const q = createMessageQueue();
q.reset('account-a:login-1');
const a = item('a', '2026-10-27T01:00:00Z'),
  b = item('b', '2026-10-27T02:00:00Z');
q.ingest([b, a, { ...a }, { ...a, id: 'bad', target: 'https://evil.invalid' }]);
assert.equal(q.count(), 2);
assert.equal(q.next().id, 'a');
q.dismiss();
assert.equal(a.readAt, undefined, 'closing an alert must not mutate its read receipt');
q.ingest([a, b]);
assert.equal(q.next().id, 'b', 'polling must not repeat dismissed alerts during a visit');
q.ingest([{ ...b, readAt: 'read' }]);
assert.equal(q.next(), null);
q.reset('account-a:login-2');
q.ingest([a, { ...b, readAt: 'read' }]);
assert.equal(q.next().id, 'a', 'a fresh login replays still-unread messages');
q.reset('account-b');
assert.equal(q.next(), null, 'switching accounts removes the previous queue');

(async () => {
  let definition,
    token = 'one',
    serial = 0,
    fail = true;
  const calls = [],
    api = {
      session: () => ({ token }),
      request: async (url, method, body) => {
        calls.push({ ...body });
        if (body.name === 'second.pdf' && fail) throw Error('offline');
        return { id: body.name };
      },
    };
  const modules = {
    '../../services/localization': { component: (d) => d },
    '../../services/privacy': { authorize: async () => {} },
    '../../services/model': { uuid: () => String(++serial) },
    '../../services/network': { configuredOrigin: () => 'https://test.invalid' },
    '../../services/api': api,
    '../../services/admin-api': api,
  };
  const wx = {
    chooseMessageFile: (o) =>
      o.success({
        tempFiles: [
          { name: 'first.pdf', path: 'a', size: 40 },
          { name: 'second.pdf', path: 'b', size: 50 },
        ],
      }),
    getFileSystemManager: () => ({ readFile: (o) => o.success({ data: 'YQ==' }) }),
  };
  vm.runInNewContext(fs.readFileSync('miniprogram/components/file-composer/index.js', 'utf8'), {
    require: (k) => modules[k],
    Component: (d) => (definition = d),
    wx,
  });
  const c = {
    ...definition.methods,
    data: { ...definition.data, conversationId: 'thread', administrator: false },
    mounted: true,
    serial: 0,
    setData(p) {
      for (const [key, value] of Object.entries(p)) {
        const m = key.match(/^rows\[(\d+)\]\.(\w+)$/);
        if (m) this.data.rows[Number(m[1])][m[2]] = value;
        else this.data[key] = value;
      }
    },
  };
  await c.choose();
  assert.equal(c.data.rows[0].state, 'ready');
  assert.equal(c.data.rows[1].state, 'failed');
  assert.throws(() => c.ids(), /重试/);
  fail = false;
  await c.upload(1);
  assert.deepEqual(Array.from(c.ids()), ['first.pdf', 'second.pdf']);
  assert.equal(
    calls.filter((x) => x.name === 'first.pdf').length,
    1,
    'successful files must not be uploaded again',
  );
  assert.equal(
    calls[1].submissionId,
    calls[2].submissionId,
    'a failed upload retries with the same idempotency key',
  );
  let finish;
  wx.getFileSystemManager = () => ({
    readFile: (o) => {
      finish = () => o.success({ data: 'YQ==' });
    },
  });
  const pending = c.upload(1),
    before = calls.length;
  token = 'different-account';
  finish();
  await pending;
  assert.equal(
    calls.length,
    before,
    'an account switch must prevent sending previously selected private files',
  );
  c.clear();
  assert.equal(c.data.rows.length, 0);
  const model = { exports: {} };
  vm.runInNewContext(fs.readFileSync('miniprogram/services/form-model.js', 'utf8'), {
    module: model,
    require: () => ({ uuid: () => '' }),
  });
  assert.throws(
    () =>
      model.exports.serialize([
        { key: 'startsAt', label: '开始时间', value: '202620-10-27', type: 'text' },
      ]),
    /4位/,
  );
  assert.equal(
    model.exports.serialize([
      { key: 'startsAt', label: '开始时间', value: '2026-10-27', type: 'text' },
    ]).startsAt,
    '2026-10-27',
  );
  const ui = fs.readFileSync('dist/shared/ui.js', 'utf8');
  const field = ui
    .slice(ui.indexOf('export function field('), ui.indexOf('export const errorHTML'))
    .replace('export ', '');
  const box = {};
  vm.runInNewContext(field + ';this.field=field', { ...box, esc: String });
  const context = { esc: String };
  vm.runInNewContext(field + ';this.make=field', context);
  assert.match(context.make('日期', 'date', 'date'), /max="9999-12-31"/);
  assert.match(context.make('日期', 'date', 'datetime-local'), /max="9999-12-31T23:59"/);
  console.log(
    'PASS message alerts: deduplication, read pruning, unread replay and account isolation; native private attachments: partial failure, retry idempotency and stale login; four-digit dates.',
  );
})().catch((e) => {
  console.error(e);
  process.exitCode = 1;
});
